#!/tmp/venv/bin/python
"""fix2.py — правки текста сокращённых ответов (adp2) после cut.py: убирает служебные оговорки и следы подготовки.
Запуск из корня репозитория. Повторный запуск безопасен."""
import re, glob, os, sys
D = '.github/answers/adp2/'
# общие правила: (регулярное выражение, замена)
G = [
    (r'(?m)^(Законного определения нет\.|Закон определения не содержит\.|Закон понятия не раскрывает\.|В законе его нет\.)\n\n', ''),
    (r'(?m)^- Подробно — в ответ(?:е|ах) на вопрос(?:ы)? [\d–]+\.\n', ''),
    (r'(?m)^Подробно — в вопросе \d+\.\n\n', ''),
    (r' Подробно — в вопросе \d+\.', ''),
    (r' \(для целей ответа\)| \(для этого вопроса\)', ''),
    (r' \(см\. раздел \d+\)', ''),
    (r' \(названия статей приведены обобщённо\)', ''),
]
# точечные правки: файл -> [(было, стало)]
S = {
 1: [('Формулировка вопроса дословно воспроизводит конституционную формулу. Согласно', 'Согласно'),
     ('(определение выводится из //ч. 1 ст. 1, ч. 1 ст. 4 и ч. 5 ст. 6 Закона о полиции//)', '(//ч. 1 ст. 1, ч. 1 ст. 4 и ч. 5 ст. 6 Закона о полиции//)')],
 9: [('Обратите внимание: граждане в', 'Граждане в')],
 11: [('Отсюда следуют три вывода, важные для ответа:', 'Отсюда следуют три вывода:')],
 12: [('Их удобно сгруппировать в четыре блока:', 'Они образуют четыре блока:')],
 19: [('; понятие выработано наукой административного права и опирается на', '; понятие опирается на')],
 21: [('; понятие выработано наукой и судебной практикой.', '.')],
 26: [('группа выделена наукой на основе анализа', 'группа выделяется на основе анализа')],
 34: [('; для ответа их удобно объединить в группы.', '; их можно объединить в группы.')],
 41: [('Их удобно запомнить как пять признаков:', 'Их пять:')],
 43: [(' Вопрос билета посвящён второму.', ''),
      ('Для запоминания порядок удобно разделить на три этапа:', 'Порядок складывается из трёх этапов:')],
 45: [('; в теории административного права их различают.', '; по содержанию их различают.'),
      ('## 4. Понятия в теории административного права', '## 4. Содержание понятий')],
 67: [('**Формы ведомственного контроля** (по на практике):', '**Формы ведомственного контроля:**')],
 79: [(' Их удобно запоминать группами. ', ''),
      ('**Основные задачи управления** (обычно называются и в положениях об управлениях):', '**Основные задачи управления:**'),
      ('общественных местах, в том числе» при', 'общественных местах», в том числе при')],
 81: [(' Он имеет пометку «для служебного пользования», поэтому его текст в открытом доступе отсутствует.', '')],
 84: [('Определение составлено по //п. 3, 5 Наставления', 'Основа определения — //п. 3, 5 Наставления'),
      (' Готового определения в акте нет.', '')],
 87: [('Готового определения в актах нет. Формулировка составлена по //п. 3, 9 Инструкции', 'Основа определения — //п. 3, 9 Инструкции')],
 89: [('Чтобы не путать, полезно помнить, кто что делает в районном органе (', 'В районном органе полномочия распределены так (')],
 93: [('Определение составлено по //ст. 21', 'Основа определения — //ст. 21')],
 97: [('; имеет пометку «для служебного пользования», не опубликован.', '.')],
 100: [('- Контроль («надзор) в области безопасности дорожного движения осуществляется посредством: федерального государственного контроля (надзора») и «надзора',
        '- Контроль (надзор) в области безопасности дорожного движения осуществляется посредством: федерального государственного контроля (надзора) и «надзора')],
 102: [('В открытых актах единого определения ДПС нет. Акты называют', 'Единого определения ДПС в нормативных актах нет. Акты называют')],
 109: [('Определение составлено по //Типовому положению о линейном отделе', 'Основа определения — //Типовое положение о линейном отделе')],
 111: [('вмешательства, в том числе» антитеррористической', 'вмешательства», в том числе антитеррористической')],
 113: [('Определение составлено по //Типовому положению о линейном отделе', 'Основа определения — //Типовое положение о линейном отделе')],
 115: [('вмешательства, в том числе» антитеррористической', 'вмешательства», в том числе антитеррористической')],
 135: [('далее — КоАП РФ. Формулировка построена на тексте статьи)', 'далее — КоАП РФ)')],
 140: [('в теории её называют примером', 'её называют примером')],
 143: [('Перечень выводится из //п. 6 ч. 1 ст. 12 Закона о полиции//:', 'Задачи вытекают из //п. 6 ч. 1 ст. 12 Закона о полиции//:')],
}
def run():
    for f in sorted(glob.glob(D + 'q*.txt')):
        n = int(os.path.basename(f)[1:4]); t0 = t = open(f, encoding='utf-8').read()
        for a, b in G: t = re.sub(a, b, t)
        for a, b in S.get(n, []):
            if a in t:
                assert t.count(a) == 1, (n, a, t.count(a)); t = t.replace(a, b)
            elif b and b in t: pass
            else: print('НЕ НАЙДЕНО', n, a[:60])
        t = re.sub(r'\n{3,}', '\n\n', t)
        if t != t0: open(f, 'w', encoding='utf-8').write(t)
if __name__ == '__main__': run()
